import { existsSync, readFileSync } from "node:fs";
import { expect, test, type Locator, type Page, type TestInfo } from "@playwright/test";
import { PRACTICE_STORAGE_KEY } from "../../src/chain/testnet/practice";

/** Shared steps for lesson e2e specs (generated by `npm run new-lesson`). */

/**
 * How long a 3D view may take to appear: three.js loads lazily and the shaders compile. Use it for the
 * first wait on a 3D scene (`data-view="3d"`, the canvas), not as a general timeout.
 */
export const LOAD_3D = 20_000;

/**
 * Marks a test that draws a 3D scene as slow (three times the timeout). On machines without a GPU
 * (CI) WebGL runs in software and every frame costs CPU; see playwright.config.ts. Wide screens open a
 * lesson in 3D by default, so a lesson test without `?view=2d` counts as 3D.
 */
export function slow3d(is3d = true) {
  test.slow(is3d, "draws a 3D scene");
}

/**
 * `slow3d()` decided by the test's title, for a spec's `beforeEach`: every test counts as 3D unless its
 * title (or its describe's) names the 2D view ("(2d)", "in the 2d view"). Wide screens open a lesson in
 * 3D, so a test that names no view is 3D. A 2D test whose title names no view is marked too: harmless.
 */
export function slow3dUnless2d(info: TestInfo) {
  slow3d(!/\b2d\b/i.test(info.titlePath.join(" ")));
}

/** A returning visitor with a route, so "/" shows the contents instead of the opening quiz. */
export async function seedRoute(page: Page, route = "newcomer") {
  await page.addInitScript((r) => {
    if (!localStorage.getItem("bon:v1")) {
      localStorage.setItem("bon:v1", JSON.stringify({ v: 1, route: r, completions: [], evidence: {} }));
    }
  }, route);
}

/**
 * For the opt-in @testnet tests: puts the saved throwaway practice key from $TESTNET_STORE (a file
 * outside the repo, see src/chain/testnet/fileStore.test-kit.ts) where the app keeps it, so a run reuses
 * the funded account instead of asking the faucet again. Does nothing without the file.
 */
export async function seedPracticeAccount(page: Page) {
  const path = process.env.TESTNET_STORE;
  if (!path || !existsSync(path)) return;
  await page.addInitScript(({ key, value }) => localStorage.setItem(key, value), {
    key: PRACTICE_STORAGE_KEY,
    value: readFileSync(path, "utf8"),
  });
}

/**
 * Presses Next in the stage bar and waits until the step number has gone up. Without that wait, a click
 * that did not move the lesson on surfaced one step later as a confusing gate failure (a still-open gate
 * on what the test thought was the next step); now it fails here, naming the step.
 */
export async function nextStep(page: Page) {
  const next = page.getByRole("button", { name: "Next step" });
  const dots = page.getByRole("navigation", { name: "Lesson steps" }).getByRole("list");
  await expect(next).toBeEnabled();
  const label = (await dots.getAttribute("aria-label")) ?? "";
  const [, now, count] = /^Step (\d+) of (\d+)$/.exec(label) ?? [];
  await next.click();
  if (now && count) {
    await expect(dots, `Next did not move on from step ${now}`).toHaveAttribute(
      "aria-label",
      `Step ${Number(now) + 1} of ${count}`,
    );
  }
}

/** Picks one answer per question (in order) in the lesson's Check, then checks them. */
export async function answerCheck(page: Page, answers: string[]) {
  const check = page.getByRole("dialog", { name: "Quick check" });
  const groups = check.getByRole("radiogroup");
  await expect(groups).toHaveCount(answers.length);
  for (const [i, a] of answers.entries()) {
    await groups.nth(i).getByRole("radio", { name: a, exact: true }).check();
  }
  await check.getByRole("button", { name: "Check answers" }).click();
  await expect(check.getByRole("status")).toHaveText(/All right/);
}

type Completion = { lessonId: string; stage: number; route: string; mode: string; evidence?: object };

/** The lesson's completion record, read through the app's test hook. */
export function completionOf(page: Page, lessonId: string) {
  return page.evaluate((id) => {
    const w = window as unknown as { __bookOfNear?: { progress?: { completions(): Completion[] } } };
    return w.__bookOfNear?.progress?.completions().find((c) => c.lessonId === id);
  }, lessonId);
}

// ---------- render on demand (#44) ----------

/**
 * Pass to `page.addInitScript` before the page loads: counts the animation-frame callbacks that issued
 * WebGL draw calls (read them with `drawnFrames`).
 */
export function countDrawnFrames() {
  const w = window as unknown as { __drawnFrames: number };
  w.__drawnFrames = 0;
  let draws = 0;
  for (const C of [window.WebGLRenderingContext, window.WebGL2RenderingContext]) {
    if (!C) continue;
    const proto = C.prototype as unknown as Record<string, (...a: unknown[]) => unknown>;
    for (const name of ["drawArrays", "drawElements", "drawArraysInstanced", "drawElementsInstanced"]) {
      const orig = proto[name];
      if (!orig) continue;
      proto[name] = function (this: unknown, ...args: unknown[]) {
        draws++;
        return orig.apply(this, args);
      };
    }
  }
  const raf = window.requestAnimationFrame.bind(window);
  window.requestAnimationFrame = (cb) =>
    raf((t) => {
      const before = draws;
      cb(t);
      if (draws > before) w.__drawnFrames++;
    });
}

/** How many frames have drawn since the page loaded (needs `countDrawnFrames`). */
export const drawnFrames = (page: Page) =>
  page.evaluate(() => (window as unknown as { __drawnFrames: number }).__drawnFrames);

/** Waits until a whole second passes without a drawn frame, then checks the next two stay empty too. */
export async function expectSettled(page: Page) {
  await expect
    .poll(
      async () => {
        const a = await drawnFrames(page);
        await page.waitForTimeout(1000);
        return (await drawnFrames(page)) - a;
      },
      { timeout: 15_000, intervals: [0] },
    )
    .toBe(0);
  const a = await drawnFrames(page);
  await page.waitForTimeout(2000);
  expect((await drawnFrames(page)) - a).toBe(0);
}

// ---------- clickable objects react (docs/book-scene.md rule 10a) ----------

/** The focusable pick button of a 3D object, by its pick label. */
export const pickButton = (page: Page, name: string) =>
  page.locator(".sk-stage .sk-pick").and(page.getByRole("button", { name, exact: true }));

/** Focusing the object's pick button (Tab) marks it hovered, the same as a mouse; leaving clears it. */
export async function expectFocusMarksHover(page: Page, name: string) {
  const button = pickButton(page, name);
  await expect(button).toHaveAttribute("data-hover", "off");
  await button.focus();
  await expect(button).toHaveAttribute("data-hover", "on");
  await button.blur();
  await expect(button).toHaveAttribute("data-hover", "off");
}

/**
 * Picking the object plays its reaction: `data-pick` goes "playing", frames are drawn, then it is "idle"
 * again and the canvas rests. Needs `page.addInitScript(countDrawnFrames)` before the page loaded.
 */
export async function expectPickPlaysAndSettles(page: Page, name: string) {
  const button = pickButton(page, name);
  await expectSettled(page);
  await button.evaluate((el) => {
    const w = window as unknown as { __pickSeen: string[] };
    w.__pickSeen = [];
    new MutationObserver(() => w.__pickSeen.push(el.getAttribute("data-pick") ?? "")).observe(el, {
      attributes: true,
      attributeFilter: ["data-pick"],
    });
  });
  const before = await drawnFrames(page);
  await button.press("Enter");
  await expect(button).toHaveAttribute("data-pick", "idle");
  await expect
    .poll(() => page.evaluate(() => (window as unknown as { __pickSeen: string[] }).__pickSeen))
    .toContain("playing");
  expect((await drawnFrames(page)) - before).toBeGreaterThan(5);
  await expectSettled(page);
}

/** Picking the object too early shows its "not yet" hint (and does not play the pick). */
export async function expectNotYetHint(page: Page, name: string, hint: string | RegExp) {
  const button = pickButton(page, name);
  await button.press("Enter");
  await expect(button).toHaveAttribute("data-hint", hint);
  const note = await pickNoteOf(button);
  await expect(note).toHaveText(hint);
  await expect(note).toHaveClass(/\bhint\b/);
  await expect(button).toHaveAttribute("data-pick", "idle");
}

/** Picking the object after its step is done shows its detail. */
export async function expectPickDetail(page: Page, name: string, detail: string | RegExp) {
  const button = pickButton(page, name);
  await button.press("Enter");
  await expect(button).toHaveAttribute("data-detail", detail);
  const note = await pickNoteOf(button);
  await expect(note).toHaveText(detail);
  await expect(note).toHaveClass(/\bdetail\b/);
}

/** The pick button's note: the live region it names in `aria-describedby`. */
async function pickNoteOf(button: Locator) {
  const id = await button.getAttribute("aria-describedby");
  expect(id).toBeTruthy();
  return button.page().locator(`[id="${id}"]`);
}
